import 'package:flutter/material.dart';
import 'package:hydrowin/app/cloud_scope.dart';
import 'package:hydrowin/core/constants/app_constants.dart';
import 'package:hydrowin/domain/models/developer_settings.dart';
import 'package:hydrowin/domain/models/network_settings.dart';
import 'package:go_router/go_router.dart';

/// Единый экран: связь блока (Wi‑Fi/GSM) + адрес сервера API.
/// Доступен только администратору клиентской организации (не производителю).
class NetworkSettingsScreen extends StatefulWidget {
  const NetworkSettingsScreen({super.key});

  @override
  State<NetworkSettingsScreen> createState() => _NetworkSettingsScreenState();
}

class _NetworkSettingsScreenState extends State<NetworkSettingsScreen> {
  bool _loading = true;
  bool _allowed = false;

  late NetworkSettings _network;
  late TextEditingController _host;
  late TextEditingController _apiPort;
  late TextEditingController _blockPort;
  late TextEditingController _apiPath;
  bool _useCustom = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _init());
  }

  Future<void> _init() async {
    final scope = CloudScope.of(context);
    final admin = await scope.auth.isAdmin();
    var manufacturer = false;
    if (admin && !await scope.tokens.isDemoSession()) {
      try {
        final me = await scope.organizations.fetchMe();
        manufacturer = me.isManufacturer;
      } catch (_) {}
    }

    if (!mounted) return;
    if (!admin || manufacturer) {
      setState(() {
        _loading = false;
        _allowed = false;
      });
      return;
    }

    _network = scope.networkSettings.load();
    final dev = scope.developerSettings.load();
    _host = TextEditingController(text: dev.serverHost);
    _apiPort = TextEditingController(text: '${dev.apiPort}');
    _blockPort = TextEditingController(text: '${dev.BLOCKPort}');
    _apiPath = TextEditingController(text: dev.apiPath);
    _useCustom = dev.useCustomServer;

    setState(() {
      _loading = false;
      _allowed = true;
    });
  }

  @override
  void dispose() {
    if (_allowed) {
      _host.dispose();
      _apiPort.dispose();
      _blockPort.dispose();
      _apiPath.dispose();
    }
    super.dispose();
  }

  Future<void> _saveLinkType(String linkType) async {
    _network = _network.copyWith(BLOCKLinkType: linkType);
    await CloudScope.of(context).networkSettings.save(_network);
    if (mounted) setState(() {});
  }

  Future<void> _saveServer() async {
    final scope = CloudScope.of(context);
    final updated = DeveloperSettings(
      serverHost: _host.text.trim(),
      apiPort: int.tryParse(_apiPort.text.trim()) ?? 8090,
      BLOCKPort: int.tryParse(_blockPort.text.trim()) ?? 80,
      apiPath: _apiPath.text.trim().isEmpty ? '/v1' : _apiPath.text.trim(),
      useCustomServer: _useCustom,
    );
    await scope.developerSettings.save(updated);
    scope.api.baseUrl = scope.serverConfig.resolveApiBaseUrl();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('Сохранено. API: ${scope.api.baseUrl}')),
    );
  }

  @override
  Widget build(BuildContext context) {
    if (_loading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (!_allowed) {
      return Scaffold(
        appBar: AppBar(
          title: const Text('Настройка блока и сети'),
          leading: BackButton(onPressed: () => context.pop()),
        ),
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(24),
            child: Text(
              'Доступно только администратору предприятия.\n'
              'Учётная запись производителя (HydroMaker) эту настройку не видит.',
              textAlign: TextAlign.center,
            ),
          ),
        ),
      );
    }

    final serverUrl = CloudScope.of(context).serverConfig.resolveApiBaseUrl();

    return Scaffold(
      appBar: AppBar(
        title: const Text('Настройка блока и сети'),
        leading: BackButton(onPressed: () => context.pop()),
      ),
      body: ListView(
        padding: const EdgeInsets.all(16),
        children: [
          Text(
            'Как блок передаёт данные на сервер',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 8),
          RadioListTile<String>(
            title: const Text('Wi‑Fi'),
            subtitle: const Text(
              'Блок в зоне Wi‑Fi, данные на сервер по беспроводной сети',
            ),
            value: AppConstants.BLOCKLinkWifi,
            groupValue: _network.BLOCKLinkType,
            onChanged: (v) => v == null ? null : _saveLinkType(v),
          ),
          RadioListTile<String>(
            title: const Text('GSM (SIM)'),
            subtitle: const Text(
              'Мобильный модем в блоке, передача через сотовую сеть',
            ),
            value: AppConstants.BLOCKLinkGsm,
            groupValue: _network.BLOCKLinkType,
            onChanged: (v) => v == null ? null : _saveLinkType(v),
          ),
          const Divider(height: 32),
          Text(
            'Сервер API (приложение и блок)',
            style: Theme.of(context).textTheme.titleMedium,
          ),
          const SizedBox(height: 4),
          Text(
            'Текущий адрес: $serverUrl',
            style: Theme.of(context).textTheme.bodySmall,
          ),
          const SizedBox(height: 8),
          SwitchListTile(
            contentPadding: EdgeInsets.zero,
            title: const Text('Свой сервер API'),
            subtitle: const Text('Иначе используется адрес из сборки'),
            value: _useCustom,
            onChanged: (v) => setState(() => _useCustom = v),
          ),
          const SizedBox(height: 8),
          TextField(
            controller: _host,
            enabled: _useCustom,
            decoration: const InputDecoration(
              labelText: 'IP или хост сервера',
              hintText: '5.165.27.141',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _apiPort,
            enabled: _useCustom,
            keyboardType: TextInputType.number,
            decoration: const InputDecoration(
              labelText: 'Порт API',
              hintText: '8090',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _apiPath,
            enabled: _useCustom,
            decoration: const InputDecoration(
              labelText: 'Путь API',
              hintText: '/v1',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _blockPort,
            decoration: const InputDecoration(
              labelText: 'Порт блока (справочно)',
              hintText: '80',
              border: OutlineInputBorder(),
            ),
          ),
          const SizedBox(height: 24),
          FilledButton(
            onPressed: _saveServer,
            child: const Text('СОХРАНИТЬ АДРЕС СЕРВЕРА'),
          ),
        ],
      ),
    );
  }
}
